                <i32>::sse_encode(1, serializer);
                <i64>::sse_encode(ms, serializer);
                <u64>::sse_encode(track_id, serializer);
                <u64>::sse_encode(item_id, serializer);
                <u64>::sse_encode(session_id, serializer);
